mp4Files.forEach(file => {
  file._calculatedDurationSec = (file.recording_start && file.recording_end) 
    ? (new Date(file.recording_end).getTime() - new Date(file.recording_start).getTime()) / 1000 
    : 0;
});

// ╨б╨╛╤А╤В╨╕╤А╤Г╨╡╨╝: ╤Б╨░╨╝╤Л╨╣ ╨┤╨╗╨╕╨╜╨╜╤Л╨╣ ╤Д╨░╨╣╨╗ ╨▒╤Г╨┤╨╡╤В ╨┐╨╡╤А╨▓╤Л╨╝ ╨▓ ╨╝╨░╤Б╤Б╨╕╨▓╨╡ [0]
