const videoFile = mp4Files[0];

// === ╨д╨Ш╨Ы╨м╨в╨а╨Р╨ж╨Ш╨п ╨Ш ╨Т╨л╨Т╨Ю╨Ф ===
if (videoFile) {
  const durationInMinutes = videoFile._calculatedDurationSec / 60;

  // ╨г╤Б╨╗╨╛╨▓╨╕╨╡ ╨┐╨╛ ╨┤╨╗╨╕╤В╨╡╨╗╤М╨╜╨╛╤Б╤В╨╕ (30 ╨╝╨╕╨╜╤Г╤В)
