      recording_type: videoFile.recording_type // ╨Ф╨╛╨▒╨░╨▓╨╕╨╗ ╨┤╨╗╤П ╨┐╤А╨╛╨▓╨╡╤А╨║╨╕ ╨▓ ╨╗╨╛╨│╨░╤Е
    }
