// ╨е╨╡╨╗╨┐╨╡╤А: ╤Б╨╡╨║╤Г╨╜╨┤╤Л тЖТ "╨з╨з:╨Ь╨Ь:╨б╨б" (╨▓ ╨╜╨╛╨▓╨╛╨╝ ╤Д╨░╨╣╨╗╨╡ ╤В╨░╨╣╨╝╨║╨╛╨┤╤Л ╤Г╨║╨░╨╖╨░╨╜╤Л ╨▓ ╤Б╨╡╨║╤Г╨╜╨┤╨░╤Е, ╨░ ╨╜╨╡ ╨╝╨╕╨╗╨╗╨╕╤Б╨╡╨║╤Г╨╜╨┤╨░╤Е)
function secToTime(sec) {
  const totalSec = Math.floor(sec);
  const h = Math.floor(totalSec / 3600).toString().padStart(2, '0');
  const m = Math.floor((totalSec % 3600) / 60).toString().padStart(2, '0');
  const s = (totalSec % 60).toString().padStart(2, '0');
  return `${h}:${m}:${s}`;
}

// ╨Я╤А╨╛╤Е╨╛╨┤╨╕╨╝ ╨┐╨╛ ╨║╨░╨╢╨┤╨╛╨╝╤Г ╤Б╨╗╨╛╨▓╤Г
for (const wordObj of words) {
  // ╨С╨╡╤А╨╡╨╝ ╤Б╨╗╨╛╨▓╨╛ ╤Б╨╛ ╨╖╨╜╨░╨║╨░╨╝╨╕ ╨┐╤А╨╡╨┐╨╕╨╜╨░╨╜╨╕╤П (punctuated_word), ╨╡╤Б╨╗╨╕ ╨╡╨│╨╛ ╨╜╨╡╤В - ╨╛╨▒╤Л╤З╨╜╨╛╨╡ (word)
  const text = (wordObj.punctuated_word || wordObj.word || "").trim();
  if (!text) continue;

  if (currentStartTime === null) {
    currentStartTime = secToTime(wordObj.start);
  }

  // ╨Ф╨╛╨▒╨░╨▓╨╗╤П╨╡╨╝ ╤Б╨╗╨╛╨▓╨╛ ╨║ ╤В╨╡╨║╤Г╤Й╨╡╨╝╤Г ╤З╨░╨╜╨║╤Г ╤Б ╨┐╤А╨╛╨▒╨╡╨╗╨╛╨╝
  currentChunk += text + " ";

  // ╨Х╤Б╨╗╨╕ ╤З╨░╨╜╨║ ╨┤╨╛╤Б╤В╨╕╨│ ╨╗╨╕╨╝╨╕╤В╨░ тАФ ╤Б╨╛╤Е╤А╨░╨╜╤П╨╡╨╝
  if (currentChunk.length >= MAX_CHARS) {
    chunks.push({
      json: {
        timestamp: currentStartTime,
        text: currentChunk.trim()
      }
    });
    currentChunk = "";
    currentStartTime = null;
  }
}

// ╨Ф╨╛╨▒╨░╨▓╨╗╤П╨╡╨╝ ╨┐╨╛╤Б╨╗╨╡╨┤╨╜╨╕╨╣ ╤Е╨▓╨╛╤Б╤В╨╕╨║, ╨╡╤Б╨╗╨╕ ╨╛╨╜ ╨╛╤Б╤В╨░╨╗╤Б╤П
if (currentChunk.length > 0) {
  chunks.push({
    json: {
      timestamp: currentStartTime,
      text: currentChunk.trim()
    }
  });
}

return chunks;

// ╨С╨╡╤А╨╡╨╝ ╨▓╤Б╨╡ ╨▓╤Е╨╛╨┤╤П╤Й╨╕╨╡ ╨║╤Г╤Б╨╛╤З╨║╨╕ ╨╕ ╤Б╨║╨╗╨╡╨╕╨▓╨░╨╡╨╝ ╨╕╤Е
// ╨д╨╛╤А╨╝╨░╤В: [00:00:14] ╨в╨╡╨║╤Б╤В... \n [00:02:30] ╨в╨╡╨║╤Б╤В...

const fullTranscript = items.map(item => {
  return `[${item.json.timestamp}] ${item.json.text}`;
}).join("\n\n");

// ╨Т╨╛╨╖╨▓╤А╨░╤Й╨░╨╡╨╝ ╨╛╨┤╨╕╨╜ ╨╛╨▒╤К╨╡╨║╤В ╨┤╨╗╤П OpenAI
return [{
  json: {
    transcript: fullTranscript
  }
}];
